// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ConfirmEmailChange Confirm a pending email change with the emailed token
	// (POST /accounts/email-change/confirm)
	ConfirmEmailChange(ctx context.Context, request ConfirmEmailChangeRequestObject) (ConfirmEmailChangeResponseObject, error)
	// DeleteCurrentAccount Delete the account and anonymize its authored content
	// (DELETE /accounts/me)
	DeleteCurrentAccount(ctx context.Context, request DeleteCurrentAccountRequestObject) (DeleteCurrentAccountResponseObject, error)
	// GetCurrentAccount Read the signed-in account
	// (GET /accounts/me)
	GetCurrentAccount(ctx context.Context, request GetCurrentAccountRequestObject) (GetCurrentAccountResponseObject, error)
	// UpdateCurrentAccount Update display name and timezone
	// (PATCH /accounts/me)
	UpdateCurrentAccount(ctx context.Context, request UpdateCurrentAccountRequestObject) (UpdateCurrentAccountResponseObject, error)
	// RemoveAvatar Remove the account avatar
	// (DELETE /accounts/me/avatar)
	RemoveAvatar(ctx context.Context, request RemoveAvatarRequestObject) (RemoveAvatarResponseObject, error)
	// UploadAvatar Replace the account avatar
	// (PUT /accounts/me/avatar)
	UploadAvatar(ctx context.Context, request UploadAvatarRequestObject) (UploadAvatarResponseObject, error)
	// DeactivateCurrentAccount Deactivate the account while preserving its authored content
	// (POST /accounts/me/deactivate)
	DeactivateCurrentAccount(ctx context.Context, request DeactivateCurrentAccountRequestObject) (DeactivateCurrentAccountResponseObject, error)
	// GetPendingEmailChange Read the pending email change, if any
	// (GET /accounts/me/email-change)
	GetPendingEmailChange(ctx context.Context, request GetPendingEmailChangeRequestObject) (GetPendingEmailChangeResponseObject, error)
	// RequestEmailChange Request a new address, which stays pending until confirmed
	// (POST /accounts/me/email-change)
	RequestEmailChange(ctx context.Context, request RequestEmailChangeRequestObject) (RequestEmailChangeResponseObject, error)
	// SetPassword Establish a password for an account created without one
	// (POST /accounts/me/password)
	SetPassword(ctx context.Context, request SetPasswordRequestObject) (SetPasswordResponseObject, error)
	// ChangePassword Replace the current password, revoking every other session
	// (PUT /accounts/me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// SignIn Exchange credentials for a session cookie
	// (POST /auth/login)
	SignIn(ctx context.Context, request SignInRequestObject) (SignInResponseObject, error)
	// SignOut Discard the current session
	// (POST /auth/logout)
	SignOut(ctx context.Context, request SignOutRequestObject) (SignOutResponseObject, error)
	// RequestPasswordReset Email a single-use password reset link
	// (POST /auth/password-reset)
	RequestPasswordReset(ctx context.Context, request RequestPasswordResetRequestObject) (RequestPasswordResetResponseObject, error)
	// ConfirmPasswordReset Set a new password with the emailed token, ending every session
	// (POST /auth/password-reset/confirm)
	ConfirmPasswordReset(ctx context.Context, request ConfirmPasswordResetRequestObject) (ConfirmPasswordResetResponseObject, error)
	// RegisterAccount Create an instance-level account
	// (POST /auth/register)
	RegisterAccount(ctx context.Context, request RegisterAccountRequestObject) (RegisterAccountResponseObject, error)
	// GetHealth Report service liveness
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// RevokeAllSessions Revoke every session for the account, including the current one
	// (DELETE /sessions)
	RevokeAllSessions(ctx context.Context, request RevokeAllSessionsRequestObject) (RevokeAllSessionsResponseObject, error)
	// ListSessions List the signed-in account's active sessions
	// (GET /sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// RevokeSession Revoke a single session immediately
	// (DELETE /sessions/{sessionId})
	RevokeSession(ctx context.Context, request RevokeSessionRequestObject) (RevokeSessionResponseObject, error)
	// ListWorkspaces List the workspaces the signed-in account belongs to
	// (GET /workspaces)
	ListWorkspaces(ctx context.Context, request ListWorkspacesRequestObject) (ListWorkspacesResponseObject, error)
	// CreateWorkspace Create a workspace with the signed-in account as its administrator
	// (POST /workspaces)
	CreateWorkspace(ctx context.Context, request CreateWorkspaceRequestObject) (CreateWorkspaceResponseObject, error)
	// GetWorkspaceAuthPolicy Read which authentication methods the workspace accepts
	// (GET /workspaces/{workspaceId}/auth-policy)
	GetWorkspaceAuthPolicy(ctx context.Context, request GetWorkspaceAuthPolicyRequestObject) (GetWorkspaceAuthPolicyResponseObject, error)
	// SetWorkspaceAuthPolicy Set which authentication methods the workspace accepts
	// (PUT /workspaces/{workspaceId}/auth-policy)
	SetWorkspaceAuthPolicy(ctx context.Context, request SetWorkspaceAuthPolicyRequestObject) (SetWorkspaceAuthPolicyResponseObject, error)
	// ListWorkspaceMembers List workspace members
	// (GET /workspaces/{workspaceId}/members)
	ListWorkspaceMembers(ctx context.Context, request ListWorkspaceMembersRequestObject) (ListWorkspaceMembersResponseObject, error)
	// AddWorkspaceMember Add an account to the workspace
	// (POST /workspaces/{workspaceId}/members)
	AddWorkspaceMember(ctx context.Context, request AddWorkspaceMemberRequestObject) (AddWorkspaceMemberResponseObject, error)
	// RemoveWorkspaceMember Remove a member from the workspace
	// (DELETE /workspaces/{workspaceId}/members/{accountId})
	RemoveWorkspaceMember(ctx context.Context, request RemoveWorkspaceMemberRequestObject) (RemoveWorkspaceMemberResponseObject, error)
	// ChangeWorkspaceMemberRole Change a member role
	// (PATCH /workspaces/{workspaceId}/members/{accountId})
	ChangeWorkspaceMemberRole(ctx context.Context, request ChangeWorkspaceMemberRoleRequestObject) (ChangeWorkspaceMemberRoleResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

